"""Save selected page images linked by official publication HTML; no OCR inference."""
import concurrent.futures, hashlib, json, re, sys
from urllib.request import Request,urlopen
from pathlib import Path
ROOT=Path(__file__).resolve().parent/'official'
JOBS={'772n':('0001202111260023',[1,4,5,6,7]),'2334':('0001202112220024',[1,2,3]),'805':('0001202606300022',[1,2,3])}
def get(job):
 name,(number,pages)=job;out=[]
 url='http://publication.pravo.gov.ru/Document/View/'+number
 try:
  r=urlopen(Request(url,headers={'User-Agent':'Mozilla/5.0'}),timeout=18);b=r.read();(ROOT/(name+'-page.html')).write_bytes(b)
  out.append({'url':url,'status':r.status,'file':name+'-page.html','sha256':hashlib.sha256(b).hexdigest()})
  match=re.search(rb"GetImage\?documentId=([0-9a-f-]+)",b)
  if not match:raise ValueError('No official page-image link')
  for n in pages:
   u='http://publication.pravo.gov.ru/GetImage?documentId='+match.group(1).decode()+'&pageNumber='+str(n)
   r=urlopen(Request(u,headers={'User-Agent':'Mozilla/5.0'}),timeout=18);b=r.read();f=f'{name}-p{n}.png'
   if not b.startswith(b'\x89PNG'):raise ValueError(f'Non-PNG image: {b[:12]!r}')
   (ROOT/f).write_bytes(b);out.append({'url':u,'status':r.status,'file':f,'bytes':len(b),'sha256':hashlib.sha256(b).hexdigest()})
 except Exception as e:out.append({'document':name,'error':str(e)})
 return out
with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:results=list(pool.map(get,JOBS.items()))
with (ROOT/'page-fetch.jsonl').open('a') as f:
 for rows in results:
  for row in rows:f.write(json.dumps(row,ensure_ascii=False)+'\n');print(json.dumps(row,ensure_ascii=False))
sys.exit(1 if any('error' in r for rows in results for r in rows) else 0)
